import time
import logging
import gpiozero
from picamera2 import PiCamera
from adafruit_circuitpython_mcp3008 import MCP3008
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(level=logging.INFO)

class SmartGardenController:
    def __init__(self):
        self.camera = PiCamera()
        self.mcp = MCP3008(ce=0, bus=0, clock=1.35e6, resolution=10)
        self.relay = gpiozero.DigitalOutput(18)
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message
        self.mqtt_client.connect("mqtt.eclipse.org", 1883, 60)

    def on_connect(self, client, userdata, flags, rc):
        logging.info("Connected to MQTT broker")

    def on_message(self, client, userdata, msg):
        logging.info(f"Received message: {msg.payload.decode()}")

    def run_pump(self, seconds):
        self.relay.on()
        time.sleep(seconds)
        self.relay.off()

    def irrigation_cycle(self):
        try:
            raw_moisture = self.mcp.read_adc(0)
            if raw_moisture < 450:
                return False
            self.run_pump(2)
            return True
        except Exception as e:
            logging.error(f"Error during irrigation cycle: {e}")
            return False

    def read_moisture(self):
        try:
            raw_moisture = self.mcp.read_adc(0)
            return raw_moisture
        except Exception as e:
            logging.error(f"Error reading moisture: {e}")
            return None

    def close(self):
        self.mcp.close()
        self.relay.close()
        self.mqtt_client.disconnect()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        controller.irrigation_cycle()
        time.sleep(interval_seconds)

def main():
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
        controller.close()
    except Exception as e:
        logging.error(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

