import time
import logging
import os
import gpiozero
import picamera2
import adafruit_mcp3008
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(filename='greenhouse.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup
pump = gpiozero.DigitalOutput(17)
fan = gpiozero.DigitalOutput(27)
light = gpiozero.DigitalOutput(22)
led = gpiozero.DigitalOutput(25)

# MCP3008 setup
mcp = adafruit_mcp3008.MCP3008()

# DHT22 setup
dht = gpiozero.DHT22(4)

# MQTT setup
mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message
mqtt_client.connect("mqtt.server.com", 1883, 60)

# Watchdog timer
watchdog_timeout = 600
last_action_time = time.time()

def on_connect(client, userdata, flags, rc):
    logging.info("MQTT connected")
    client.subscribe("greenhouse/status")

def on_message(client, userdata, msg):
    logging.info(f"Received message: {msg.topic} {msg.payload.decode()}")

def control_pump(command):
    global pump
    if command.lower() == "on":
        pump.on
    elif command.lower() == "off":
        pump.off

def control_fan(command):
    global fan
    if command.lower() == "on":
        fan.on
    elif command.lower() == "off":
        fan.off

def control_light(command):
    global light
    if command.lower() == "on":
        light.on
    elif command.lower() == "off":
        light.off

def set_led_status(mode):
    global led
    if mode == "online":
        led.on
    elif mode == "offline":
        led.off
    elif mode == "error":
        led.blink(5, 0.2)
    elif mode == "synchronizing":
        led.blink(5, 0.2)

def read_dht22():
    try:
        humidity, temperature = dht.measure()
        logging.info(f"DHT22: Humidity: {humidity:.1f}%, Temperature: {temperature:.1f}°C")
        return humidity, temperature
    except Exception as e:
        logging.error(f"DHT22 error: {e}")
        return None, None

def read_mcp3008():
    try:
        channel_value = mcp.channel_read(0)
        logging.info(f"MCP3008 Channel 0: {channel_value}")
        return channel_value
    except Exception as e:
        logging.error(f"MCP3008 SPI error: {e}")
        return None

def main():
    while True:
        try:
            # Read DHT22 data
            humidity, temperature = read_dht22()
            if humidity is not None and temperature is not None:
                logging.info(f"DHT22: {humidity:.1f}%, {temperature:.1f}°C")

            # Read MCP3008 data
            analog_value = read_mcp3008()
            if analog_value is not None:
                logging.info(f"MCP3008: {analog_value}")

            # Process actuator commands
            command = input("Enter command (on/off/pump/fan/light/led): ")
            if command.lower() in ["on", "off"]:
                control_pump(command.lower())
                control_fan(command.lower())
                control_light(command.lower())
            elif command.lower() in ["pump", "fan", "light"]:
                control_pump(command.lower())
                control_fan(command.lower())
                control_light(command.lower())
            elif command.lower() == "led":
                mode = input("Enter LED mode (online/offline/error/synchronizing): ")
                set_led_status(mode)

            # Check for watchdog timeout
            if time.time() - last_action_time > watchdog_timeout:
                logging.warning("Watchdog timeout, restarting...")
                os.execv(os.path.realpath(__file__), [os.path.realpath(__file__)])
                last_action_time = time.time()

        except KeyboardInterrupt:
            logging.info("Exiting gracefully")
            break
        except Exception as e:
            logging.error(f"An error occurred: {e}")

if __name__ == "__main__":
    main()

