            self.mcp3008.channel_0_channel_cs = 0
            raw_value = self.mcp3008.read_adc(0)
            ppm = self.convert_raw_to_ppm(raw_value)
            alert_level = self.get_alert_level(ppm)
            print(f"Raw Value: {raw_value}, PPM: {ppm}, Alert Level: {alert_level}")
            self.publish_to_mqtt(ppm, alert_level)

    def convert_raw_to_ppm(self, raw_value):
        # Assuming a linear relationship between ADC value and ppm
