                return level
        return "safe"

    def publish_to_mqtt(self, ppm, alert_level):
        self.mqtt_client.publish(self.mqtt_topic, f"{ppm} {alert_level}")

    def run(self):
        while True:
            self.read_sensor()
            time.sleep(0.5)

