import time
import logging
import gc
from contextlib import contextmanager
from gpiozero import DHT20
from picamera2 import I2C
from adafruit_circuitpython_dht import DHT

logging.basicConfig(level=logging.WARNING)

class DHT20Driver:
    def __init__(self, i2c_bus=1):
        self.i2c = I2C(bus=i2c_bus)
        self.dht = DHT.DHT20(self.i2c)
        self.attempts = 0
        self.max_attempts = 5
        self.retry_interval = 0.01
        self.min_interval = 2.0
        self.max_retries = 10
        self.retry_timeout = 0.8
        self.crc_threshold = 0x08

    def begin(self):
        time.sleep(0.5)
        while self.attempts < self.max_attempts:
            try:
                data = self.dht.read()
                if data[5] == self.crc_threshold:
                    return data[0:6]  # Return temperature and humidity
            except OSError as e:
                logging.warning(f"OSError: {e}")
                if e.errno == 11:  # Timeout
                    time.sleep(0.01)
                elif e.errno == 12:  # Bus error
                    break
                else:
                    raise
            except Exception as e:
                logging.warning(f"Unexpected error: {e}")
            self.attempts += 1
            if self.attempts >= self.max_attempts:
                return None, None, True

        return None, None, True

    @contextmanager
    def __enter__(self):
        try:
            yield self
        finally:
            self.close()

    def close(self):
        self.i2c.close()

    def get_temperature_and_humidity(self):
        if self.attempts >= self.max_attempts:
            return None, None, True

        if self.attempts < self.max_attempts:
            time.sleep(self.min_interval)

        data = self.begin()
        if data is not None:
            self.attempts = 0
            return data[0], data[1], False

@contextmanager
def dht20_demo():
    driver = DHT20Driver()
    try:
        yield driver
    finally:
        driver.close()

if __name__ == "__main__":
    with dht20_demo() as driver:
        try:
            temp, hum, success = driver.get_temperature_and_humidity()
            if success:
                print(f"Temperature: {temp}°C, Humidity: {hum}%")
        except Exception as e:
            print(f"Demo failed: {e}")
            exit(1)

