class RotaryEncoder:
    def __init__(self, callback=None):
        self.callback = callback
        self.clk = gpiozero.InputPin(17, pull_up=True)
        self.dt = gpiozero.InputPin(18, pull_up=True)
        self.debounce_timer = None
        self.state = 0
        self.counter = 0

    def debounce(self, pin, interval=20):
        def debounced(pin):
            nonlocal self.debounce_timer
            now = time.time()
            if self.debounce_timer is not None and now - self.debounce_timer < interval:
                return self.state
            self.debounce_timer = now
            self.state = pin.value
            return self.state

        self.clk.read_continuous(debounced)
        self.dt.read_continuous(debounced)

    def _update_state(self):
        self.state = self.clk.value ^ self.dt.value

    def _update_counter(self):
        global self.counter
        if self.state == 0:
            self.counter += 1
        elif self.state == 1:
            self.counter -= 1
        if self.callback and self.counter != self.last_counter:
            self.callback(self.counter)
            self.last_counter = self.counter

    def start(self):
        self.last_counter = 0
        self.debounce()
        self.thread = threading.Thread(target=self._run)
        self.thread.start()

    def _run(self):
        while True:
            try:
                self._update_state()
                self._update_counter()
                time.sleep(0.01)
            except Exception as e:
                print(f"An error occurred: {e}")
                break

    def stop(self):
        self.clk.close()
        self.dt.close()
        self.thread.join()

    def cleanup(self):
        self.clk.close()
        self.dt.close()

