        current_time = time.time()
        if current_time - self.last_read_time < self.debounce_interval:
            return False
        self.last_read_time = current_time
        return True

    def _read_encoder(self):
        while True:
            try:
                self.last_clk = GPIOZero.input(self.clk_pin)
                self.last_dt = GPIOZero.input(self.dt_pin)

                if not self._is_debounced(self.clk_pin):
                    continue

                if self.last_clk != GPIOZero.input(self.clk_pin):
                    self.counter += 1 if self.last_dt else -1

                if abs(self.counter) > 1:
                    self.counter = 0

                if self.callback:
                    self.callback(self.counter)

            except Exception as e:
                print(f"Error reading encoder: {e}")

            time.sleep(0.01)

    def start(self):
        self.debounce_thread = threading.Thread(target=self._read_encoder)
        self.debounce_thread.start()

    def stop(self):
        if self.debounce_thread:
            self.debounce_thread.join()
            self.debounce_thread = None

    def cleanup(self):
        if self.debounce_thread:
            self.debounce_thread.terminate()
            self.debounce_thread.join()

class MQTTPublisher:
    def __init__(self, topic, client_id, callback=None):
        self.topic = topic
        self.client_id = client_id
        self.callback = callback
        self.client = mqtt.Client(client_id)
        self.client.on_connect = self.on_connect
        self.client.on_message = self.on_message

    def connect(self):
        self.client.connect("mqtt.eclipse.org", 1883, 60)

    def on_connect(self, client, userdata, flags, rc):
        if rc == 0:
            print("Connected to MQTT Broker")
            self.client.subscribe(self.topic)

    def on_message(self, client, userdata, msg):
        if self.callback:
            self.callback(msg.payload.decode())

    def publish(self, message):
        self.client.publish(self.topic, message)

def rotary_encoder_callback(counter):
    print(f"Encoder Counter: {counter}")

def main():
    clk_pin = 17
    dt_pin = 18

    encoder = RotaryEncoder(clk_pin, dt_pin, rotary_encoder_callback)
    encoder.start()

    mqtt_publisher = MQTTPublisher("home/automation", "raspberrypi_encoder", rotary_encoder_callback)
    mqtt_publisher.connect()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        encoder.stop()
        mqtt_publisher.cleanup()

if __name__ == "__main__":
    main()
```

This code defines a `RotaryEncoder` class that reads a KY-040 rotary encoder using GPIO pins 17 (CLK) and 18 (DT) with internal pull-up resistors. It includes a debounce mechanism, a callback function for handling state changes, and a cleanup method to safely release GPIO resources. The `main` function sets up the encoder, starts the reading thread, connects to an MQTT broker, and handles keyboard interrupts to gracefully stop and clean up resources.

