logging.basicConfig(level=logging.INFO)

class ChassisController:
    def __init__(self, digital_output_device):
        self.digital_output_device = digital_output_device
        self.motors = {
            17: gpiozero.DigitalOutput(17),
            18: gpiozero.DigitalOutput(18),
            22: gpiozero.DigitalOutput(22),
            23: gpiozero.DigitalOutput(23),
            12: gpiozero.DigitalOutput(12),
            13: gpiozero.DigitalOutput(13)
        }

    def drive_forward(self, speed_fraction):
        for motor, output in self.motors.items():
            output.value = True
        time.sleep(0.5 * speed_fraction)

    def turn_left(self, speed_fraction):
        for motor, output in self.motors.values():
            output.value = True
        time.sleep(0.5 * speed_fraction)

    def stop_all(self):
        for motor, output in self.motors.items():
            output.value = False

    def read_tilt(self):
        # Simulated tilt readings
        tilt_readings = [25, -25, 0, 30, -15, 40, -30, 10]
        return tilt_readings

class DigitalOutputDevice:
    def __init__(self, pins):
        self.pins = pins

    def enable_motors(self):
        self.pins[12].value = True
        self.pins[13].value = True

# Initialize GPIO
try:
    digital_output_device = DigitalOutputDevice(
        [gpiozero.GPIO(12), gpiozero.GPIO(13)]
    )
    ChassisController(digital_output_device).enable_motors()
except gpiozero.GPIOError as e:
    logging.error(f"GPIO initialization failed: {e}")
    exit(1)

# Tilt readings and commands
tilt_readings = ChassisController(digital_output_device).read_tilt()

for tilt in tilt_readings:
    logging.info(f"Tilt: {tilt}")

    if tilt > 20:
        ChassisController(digital_output_device).drive_forward(0.5)
        logging.info("Driving forward")
    elif tilt < -20:
        ChassisController(digital_output_device).turn_left(0.5)
        logging.info("Turning left")
    else:
        ChassisController(digital_output_device).stop_all()
        logging.info("Stopped")

    time.sleep(0.5)

# MQTT setup (optional, for remote control)
mqtt_client = mqtt.Client()
mqtt_client.connect("mqtt.eclipse.org", 1883, 60)
mqtt_client.publish("rover/status", "Tilt readings and commands executed.")

# Signal handlers for SIGINT and SIGTERM
def on_sigint(signum, frame):
    logging.info("Received SIGINT, stopping...")
    ChassisController(digital_output_device).stop_all()
    digital_output_device.enable_motors()
    exit(0)

def on_sigterm(signum, frame):
    logging.info("Received SIGTERM, stopping...")
    ChassisController(digital_output_device).stop_all()
    digital_output_device.enable_motors()
    exit(0)

signal.signal(signal.SIGINT, on_sigint)
signal.signal(signal.SIGTERM, on_sigterm)

# Run the motor control loop
