    def __init__(self, i2c_address=0x40):
        try:
            self.pca9685 = PCA9685(i2c_bus=i2c_bus.I2C(0), address=i2c_address)
            self.pca9685.frequency = 60
            self.pca9685.min_pulse_width = 150e-6
            self.pca9685.max_pulse_width = 600e-6
        except (ValueError, OSError) as e:
            logging.error(f"PCA9685 initialization failed: {e}")
            raise SystemExit(1)

        self.claw = PWMOutputDevice(self.pca9685.channels[0], i2c_bus.I2C(0))
        self.lock = PWMOutputDevice(self.pca9685.channels[1], i2c_bus.I2C(0))
        self.water_gun = PWMOutputDevice(self.pca9685.channels[2], i2c_bus.I2C(0))

    def move_servo(self, channel, angle):
        if channel not in [0, 1, 2]:
            raise ValueError("Invalid channel")
        if not (-77 <= angle <= 77):
            raise ValueError("Angle out of range")

        pulse_width = int((angle + 77) * 180 / 255 * 1000000 / 60)
        self.pca9685.channels[channel].duty_cycle = pulse_width
        time.sleep(0.029)
        self.pca9685.channels[channel].duty_cycle = 0

    def bite(self):
        self.move_servo(0, -75)

    def open_claw(self):
        self.move_servo(0, 75)

    def lock(self):
        self.move_servo(1, 75)

    def unlock(self):
        self.move_servo(1, -75)

    def shoot(self):
        self.move_servo(2, -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo(2, 75)

    def setup_camera(self):
        self.camera = PiCamera()
        self.camera.resolution = (640, 480)
        self.camera.framerate = 30

    def mqtt_setup(self, broker, topic):
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.connect(broker, 1883)
        self.mqtt_client.on_message = self.on_message
        self.mqtt_client.subscribe(topic)

    def on_message(self, client, userdata, message):
        logging.info(f"Received message: {message.payload.decode()}")

    def run(self):
        self.setup_camera()
        self.mqtt_setup("mqtt.eclipse.org", "fuchikoma/state")
        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            self.cleanup()

if __name__ == "__main__":
    fuchikoma = Fuchikoma()
    fuchikoma.run()

