import time
import logging
import paho.mqtt.client as mqtt
from gpiozero import Button, LED
from picamera2 import PiCamera
import adafruit_circuitpython_displayio as displayio
import adafruit_circuitpython_ssd1306 as ssd1306
import numpy as np
from gpiozero import GPIOZeroError

# Initialize GPIO pins
SENSOR_A_TRIGGER = 17
SENSOR_A_ECHO = 18
SENSOR_B_TRIGGER = 22
SENSOR_B_ECHO = 23
AUGER_RELAY = 27

# Initialize display (assuming OLED display)
display = displayio.Group()
with ssd1306.Display(128, 64, displayio.PinOUT, 12, 13, 4, 5, 6, 7) as display:
    display.show(np.zeros((128, 64), dtype=np.uint8) * 0xFF)

# Initialize MQTT client
mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message

# Initialize variables
fill_level_history = []
container_present = False
refill_triggered = False
refill_cooldown = 0

def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker")
    mqtt_client.subscribe("bird_feeder/status")

def on_message(client, userdata, msg):
    global fill_level_history, container_present, refill_triggered
    data = msg.payload.decode()
    logging.info(f"Received MQTT message: {data}")
    if data == "fill_level":
        fill_level_history.append(int(data))
    elif data == "container_present":
        container_present = True
    elif data == "refill_triggered":
        refill_triggered = True
    elif data == "refill_cooldown_expired":
        refill_cooldown = 0

def initialize_gpio():
    for pin in [SENSOR_A_TRIGGER, SENSOR_A_ECHO, SENSOR_B_TRIGGER, SENSOR_B_ECHO, AUGER_RELAY]:
        try:
            GPIO.setup(pin, GPIO.OUT)
        except GPIOZeroError as e:
            logging.error(f"Failed to initialize GPIO {pin}: {e}")
            return False
    return True

def read_sensor(trigger, echo):
    try:
        trigger.value = GPIO.HIGH
        time.sleep(0.00001)
        echo_value = GPIO.input(echo)
        trigger.value = GPIO.LOW
        return echo_value
    except GPIOZeroError as e:
        logging.error(f"Failed to read sensor: {e}")
        return None

def compute_moving_average(readings):
    if len(readings) < 3:
        return np.mean(readings)
    return np.mean(readings[-3:])

def is_low_fill_level():
    if len(fill_level_history) < 3:
        return False
    avg_fill_level = compute_moving_average(fill_level_history[-3:])
    return avg_fill_level > 10

def is_container_present():
    return container_present

def trigger_refill():
    global refill_triggered, refill_cooldown
    if refill_triggered and not refill_cooldown:
        refill_cooldown = 60
        # Activate relay for 5 seconds
        GPIO.output(AUGER_RELAY, GPIO.HIGH)
        time.sleep(5)
        GPIO.output(AUGER_RELAY, GPIO.LOW)
        refill_triggered = False
        refill_cooldown = 60
    elif refill_cooldown > 0:
        refill_cooldown -= 1

def main():
    try:
        if not initialize_gpio():
            return

        while True:
            fill_level_a = read_sensor(SENSOR_A_ECHO, SENSOR_A_TRIGGER)
            fill_level_b = read_sensor(SENSOR_B_ECHO, SENSOR_B_TRIGGER)

            if fill_level_a is not None and fill_level_b is not None:
                if fill_level_a < 15 and fill_level_b:
                    container_present = True
                elif fill_level_a >= 10:
                    fill_level_history.append(fill_level_a)
