import adafruit_mpu6050
import picamera
import paho.mqtt.client as mqtt
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# I2C bus setup
i2c = busio.I2C(board.SCL, board.SDA)
mpu = adafruit_mpu6050.MPU6050(i2c)

# MQTT setup
mqtt_broker = "your_mqtt_broker_address"
mqtt_port = 1883
mqtt_topic = "quality_control"
client = mqtt.Client()
client.on_connect = on_connect
client.on_message = on_message

def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker with result code " + str(rc))
    client.subscribe(mqtt_topic)

def on_message(client, userdata, msg):
    logging.info("Received message: " + msg.payload.decode())

def sample_vibration():
    try:
        logging.info("Starting vibration sampling...")
        samples = []
        for _ in range(8):
            try:
                accel_data = mpu.acceleration_read()
                samples.append(accel_data.magnitude)
                time.sleep(0.01)  # 10ms delay
            except Exception as e:
                logging.error("Error reading accelerometer: " + str(e))
                return

        rms_magnitude = calculate_rms(samples)
        variance = calculate_variance(samples)

        logging.info("Vibration sampling complete.")

        if rms_magnitude > 2.5 or variance > 0.4:
            log_defective("Magnitude exceeded threshold")
        else:
            log_pass()

    except Exception as e:
        logging.error("An error occurred: " + str(e))

def calculate_rms(samples):
    return (sum(x**2 for x in samples)) ** 0.5 / len(samples)

def calculate_variance(samples):
    mean = sum(samples) / len(samples)
    return sum((x - mean)**2 for x in samples) / len(samples)

def log_defective(message):
    global client
    client.publish(mqtt_topic, message)
    logging.info(message)

def log_pass():
    global client
    client.publish(mqtt_topic, "PASS")
    logging.info("PASS")

if __name__ == "__main__":
    try:
        while True:
            sample_vibration()
    except KeyboardInterrupt:
        logging.info("Exiting gracefully.")
    except Exception as e:
        logging.error("An unexpected error occurred: " + str(e))
    finally:
        mpu.close()
        client.close()

