import pigpio
import numpy as np

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup
GPIO_FORWARD = 20
GPIO_REVERSE = 21
PWM_PIN = 12

def setup_gpio():
    try:
        gpio = pigpio.pi()
        gpio.setmode(pigpio.BOARD)
        gpio.setup([GPIO_FORWARD, GPIO_REVERSE, PWM_PIN], pigpio.OUTPUT)
        gpio.write(GPIO_FORWARD, 1)  # Default to forward
        gpio.write(GPIO_REVERSE, 0)
        logging.info("GPIO setup successful.")
        return gpio
    except pigpio.Error as e:
        logging.error(f"Error setting up GPIO: {e}")
        return None

def set_direction(direction):
    if direction not in ['forward', 'reverse']:
        logging.error("Invalid direction. Must be 'forward' or 'reverse'.")
        return False
    try:
        gpio.write(GPIO_FORWARD, direction == 'forward')
        gpio.write(GPIO_REVERSE, not direction == 'forward')
        logging.info(f"Direction set to {direction}.")
        return True
    except pigpio.Error as e:
        logging.error(f"Error setting direction: {e}")
        return False

def ramp_speed(start_duty, end_duty, steps=30):
    if start_duty > end_duty:
        logging.error("Start duty cycle must be less than end duty cycle.")
        return False
    try:
        for duty in np.linspace(start_duty, end_duty, steps):
            gpio.write(PWM_PIN, duty)
            time.sleep(0.033)  # 30ms step delay
        logging.info(f"Speed ramped from {start_duty}% to {end_duty}%.")
        return True
    except pigpio.Error as e:
        logging.error(f"Error ramping speed: {e}")
        return False

def main():
    try:
        gpio = setup_gpio()
        if gpio is None:
            return

        while True:
            direction = input("Enter 'forward' or 'reverse' to set direction, or 'r' to ramp speed: ").strip().lower()
            if direction == 'r':
                ramp_speed(0, 80)
            elif direction in ['forward', 'reverse']:
                set_direction(direction)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")

    finally:
        try:
            gpio.stop()
            logging.info("PWM stopped.")
        except pigpio.Error as e:
            logging.error(f"Error stopping PWM: {e}")
        finally:
            gpio.cleanup()
            logging.info("GPIO resources released.")

if __name__ == "__main__":
    main()

