        self.driver_instance.set_pwm_duty_cycle(self.pin, freq)

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or duty < 0 or duty > 255:
            raise MotorError("Invalid duty cycle. Expected an integer between 0 and 255.")
        self.driver_instance.set_pwm_duty_cycle(self.pin, duty)

