from gpiozero import LED
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(filename='vibration_motor.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Vibration motor setup
vibration_motor = LED(17)

# MQTT setup
mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message

# Schedule for vibration
schedule_time = time.strptime("21:14", "%H:%M")

def on_connect(client, userdata, flags, rc):
    logging.info("MQTT client connected")
    client.subscribe("vibration_topic")

def on_message(client, userdata, msg):
    logging.info(f"Received message: {msg.payload.decode()}")

def vibrate_motor(duration):
    try:
        vibration_motor.on()
        time.sleep(duration)
        vibration_motor.off()
        logging.info("Vibration completed")
    except Exception as e:
        logging.error(f"Error during vibration: {e}")

def main_loop():
    while True:
        try:
            # Check if it's time to vibrate
            current_time = time.localtime()
            if current_time.tm_hour == schedule_time.tm_hour and current_time.tm_min == schedule_time.tm_min:
                vibrate_motor(30)
            else:
                logging.info("Not scheduled time for vibration")
        except Exception as e:
            logging.error(f"Unexpected error: {e}")

        # MQTT check
        mqtt_client.loop_start()

def shutdown():
    try:
        vibration_motor.off()
        logging.info("Shutting down...")
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
        logging.info("All resources released.")
