import smbus
import time
from contextlib import contextmanager
from datetime import datetime

class DS1338RTC:
    DEVICE_ADDRESS = 0x68  # I2C address of DS1338 RTC

    def __init__(self):
        self.bus = smbus.SMBus(1)
        self.ds1338 = self.bus.write_i2c_block_data(self.DEVICE_ADDRESS, 0x00, [0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])

    @contextmanager
    def i2c_bus(self):
        try:
            yield self.bus
        finally:
            self.bus.close()

    def read_all(self):
        try:
            data = self.bus.read_i2c_block_data(self.DEVICE_ADDRESS, 0x00, 16)
            year, month, date, day, hours, minutes, seconds = self.decode_bcd(data)
            return (year, month, date, day, hours, minutes, seconds)
        except IOError as e:
            raise IOError(f"Error reading from DS1338: {e}")

    def decode_bcd(self, data):
        year = (data[0] << 8) | data[1]
        month = (data[2] << 8) | data[3]
        date = (data[4] << 8) | data[5]
        day = (data[6] << 8) | data[7]
        hours = (data[8] << 8) | data[9]
        minutes = (data[10] << 8) | data[11]
        seconds = (data[12] << 8) | data[13]

        # Mask CH bit on seconds
        seconds &= 0x7F

        # Mask 12/24-hour bit on hours
        if data[9] & 0x40:
            hours = (hours << 4) | 0x30
        else:
            hours = (hours << 4) | 0x3E

        return year, month, date, day, hours, minutes, seconds

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(2000 + year, month, date, day, hours, minutes, seconds).replace(tzinfo=datetime.timezone.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (0 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")

        bcd_year = self.bcd_to_int(year)
        bcd_month = self.bcd_to_int(month)
        bcd_date = self.bcd_to_int(date)
        bcd_day = self.bcd_to_int(day)
        bcd_hours = self.bcd_to_int(hours)
        bcd_minutes = self.bcd_to_int(minutes)
        bcd_seconds = self.bcd_to_int(seconds)

        self.bus.write_i2c_block_data(self.DEVICE_ADDRESS, 0x00, [
            bcd_year, bcd_month, bcd_date, bcd_day, bcd_hours, bcd_minutes, bcd_seconds
        ])

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.dayofmonth, dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_all(datetime.now().year, datetime.now().month, datetime.now().day, datetime.now().dayofmonth,
                        datetime.now().hour, datetime.now().minute, datetime.now().second)

    @staticmethod
    def bcd_to_int(bcd):
        return int(str(bcd), 10)

def main():
    try:
        with DS1338RTC() as rtc:
            print("Current time:", rtc.read_datetime())
    except IOError as e:
        print(f"Error: {e}", file=sys.stderr)
        exit(1)

if __name__ == "__main__":
    main()

