import serial
import time
import paho.mqtt.client as mqtt
from gpiozero import Button
import adafruit_esp8266.esp8266_serial as ESP8266Serial

class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.serial_port = serial.Serial(port, baudrate=baud_rate, timeout=timeout)
        self.serial_port.open()
        if not self.serial_port.in_waiting:
            raise Exception("Failed to open UART port")

    def _send_command(self, command, timeout=1.0):
        start_time = time.time()
        response = b''
        while time.time() - start_time < timeout:
            if self.serial_port.in_waiting > 0:
                line = self.serial_port.readline().decode('utf-8').strip()
                if line in ['OK', 'ERROR', 'FAIL']:
                    break
                response += line + b'\n'
            time.sleep(0.1)
        if not response.endswith(b'\n'):
            response += b'\n'
        return response

    def test_connection(self):
        self._send_command('AT')
        response = self._send_command(b'OK', timeout=1.0)
        if response != b'OK\r\n':
            raise Exception("Failed to get 'OK' response")

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)
        self.test_connection()

    def connect_wifi(self, ssid, password):
        self._send_command('AT+CWJAP="' + ssid + ':' + password + '"', timeout=10.0)
        self.test_connection()

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP', timeout=1.0)

    def get_ip(self):
        self._send_command('AT+CIFSR', timeout=1.0)
        response = self._send_command(b'', timeout=1.0)
        if response.startswith(b'IP:'):
            return response[4:].split(b':')[1].decode('utf-8')
        else:
            raise Exception("Failed to get IP address")

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        self._send_command('AT+CIPSTART="TCP",' + host + ','+ str(port))
        self._send_command(method.upper() + ' ' + url, timeout=10.0)
        if headers:
            self._send_command('AT+CIPSEND=' + str(len(headers)) + ',0,' + ','.join(headers) + b'\r\n')
        if data:
            self._send_command('AT+CIPSEND=' + str(len(data)) + ',0,' + ','.join(data) + b'\r\n')
        response = self._send_command(b'', timeout=10.0)
        return response

    def receive_http_response(self, timeout=5.0):
        response = b''
        while True:
            chunk = self.serial_port.read(1024)
            if not chunk:
                break
            response += chunk
            if b'+IPD,' + str(len(chunk)) + b':' + chunk[:chunk.index(b':')] in response:
                return response[response.index(b'+IPD,' + str(len(chunk)) + b':') + len(b'+IPD,' + str(len(chunk)) + b':'):].decode('utf-8')

# MQTT setup
def on_connect(client, userdata, flags, rc):
    print("Connected with result code " + str(rc))

def on_message(client, userdata, msg):
    print(msg.topic + " " + str(msg.payload))

def on_disconnect(client, userdata, rc):
    print("Disconnected with reason: " + str(rc))

def on_log(client, userdata, level, buf):
    print("Log message: " + buf)

mqtt_client = mqtt.Client()
mqtt_client.on_connect = on_connect
mqtt_client.on_message = on_message
mqtt_client.on_disconnect = on_disconnect
mqtt_client.on_log = on_log

mqtt_client.connect("mqtt.eclipse.org", 1883, 60)

# Example usage
try:
    controller = ESP8266Controller()
    controller.test_connection()
    controller.connect_wifi('MySSID', 'MyPassword')
    ip_address = controller.get_ip()
    print(f"Connected IP: {ip_address}")
    controller.send_http_request('GET', 'http://example.com', 'example.com')
    response = controller.receive_http_response(5.0)
    print(f"HTTP Response: {response}")
except Exception as e:
    print(f"Error: {e}")
finally:
    controller.serial_port.close()
