    longitude: float
    altitude: int
    satellite_count: int

class GPSReader:
    def __init__(self):
        self.serial = None
        self.gps_readings = []
        self.running = True
        self.stop_event = threading.Event()

    def connect(self):
        try:
            self.serial = SerialPort('/dev/serial0', 9600, timeout=1)
            logging.info("Connected to GPS module")
        except Exception as e:
            logging.error(f"Failed to connect to GPS module: {e}")

    def disconnect(self):
        if self.serial:
            self.serial.close()
            self.serial = None
            logging.info("Disconnected from GPS module")

    def read_gps(self):
        while self.running:
            try:
                if self.serial.in_waiting > 0:
                    line = self.serial.readline().decode('utf-8').strip()
                    if line.startswith('$GPGGA'):
