                                satellites = int(parts[6])
                                latitude = float(f"{lat_deg}:{lat_min}:{lat_sec}")
                                longitude = float(f"{lon_deg}:{lon_min}:{lon_sec}")
                                self.gps_readings.append(GPS_readings(latitude, longitude, altitude, satellites))
                            else:
                                logging.warning(f"Invalid GPGGA sentence: {line}")
                        except (ValueError, IndexError) as e:
                            logging.error(f"Error parsing GPGGA sentence: {e}")
            except TimeoutError:
                logging.warning("GPS read timed out")
            except Exception as e:
                logging.error(f"Unexpected error: {e}")

