import paho.mqtt.client as mqtt

class SimpleGPS:
    def __init__(self):
        self.ser = None
        self.data_line = None

    def connect(self):
        try:
            self.ser = serial.Serial('/dev/serial0', 9600, timeout=1)
            logging.info("Connected to GPS module")
            return True
        except OSError as e:
            logging.error(f"Failed to connect to GPS module: {e}")
            return False

    def read_data(self):
        if not self.ser:
            return None

        try:
            self.data_line = self.ser.readline().decode('utf-8').strip()
            if not self.data_line:
                return None

            return self.data_line
        except Exception as e:
            logging.error(f"Error reading data: {e}")
            return None
        finally:
            self.ser.flush()

    def parse_gga(self, line):
        try:
            data = {}
            if line.startswith('$GPGGA'):
                fields = line[6:].split()
                data['utc_time'] = fields[0]
                data['latitude'] = float(fields[2])
                data['longitude'] = float(fields[4])
                data['fix_quality'] = int(fields[5])
                data['num_satellites'] = int(fields[7])
            elif line.startswith('$GNGGA'):
                fields = line[6:].split()
                data['utc_time'] = fields[0]
                data['latitude'] = float(fields[2])
                data['longitude'] = float(fields[4])
                data['fix_quality'] = int(fields[5])
                data['num_satellites'] = int(fields[7])
            else:
                logging.warning(f"Unexpected GGA line: {line}")
                return None

            return data
        except (IndexError, ValueError):
            logging.warning("Malformed GGA line, returning None")
            return None

    def close(self):
        if self.ser:
            self.ser.close()
            self.ser = None

def on_connect(client, userdata, flags, rc):
    logging.info("Connected to MQTT broker")

def on_message(client, userdata, msg):
    gps_data = SimpleGPS().parse_gga(msg.payload.decode())
    if gps_data:
