import threading
import socket
import time
import json
import paho.mqtt.client as mqtt
from gpiozero import Button
from picamera2 import PiCamera
import adafruit_circuitpython_ads1x15 as ads1x15
import adafruit_circuitpython_adafruit_display_text as display_text
import adafruit_circuitpython_adafruit_ssd1306 as adafruit_ssd1306
import gpiozero
from gpiozero.pins import UP

# Global variables
UART_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1
LOCK = threading.Lock()
UART_CONNECTION = None
DATA_LIST = [("Item1", True), ("Item2", False)]

class UARTManager:
    def __init__(self):
        self.lock = LOCK

    def open_connection(self):
        global UART_CONNECTION
        with self.lock:
            if UART_CONNECTION is None:
                try:
                    UART_CONNECTION = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
                    UART_CONNECTION.connect(UART_PORT)
                    print("UART connection established.")
                except Exception as e:
                    print(f"Error opening UART connection: {e}")

    def close_connection(self):
        global UART_CONNECTION
        with self.lock:
            if UART_CONNECTION:
                UART_CONNECTION.close()
                UART_CONNECTION = None
                print("UART connection closed.")

    def read_response(self):
        global UART_CONNECTION
        with self.lock:
            if not UART_CONNECTION:
                return "HTTP 500: UART connection not open."
            try:
                response = UART_CONNECTION.recv(TIMEOUT).decode('utf-8')
                if not response:
                    return "HTTP 504: Timeout."
                return response
            except Exception as e:
                return "HTTP 502: API call error."

class WebService:
    def __init__(self):
        self.app = mqtt.Client()
        self.app.on_connect = self.on_connect
        self.app.on_message = self.on_message
        self.app.connect("0.0.0.0", 5000, 60)
        self.app.loop_start()

    def on_connect(self, client, userdata, flags, rc):
        print(f"Connected with result code {rc}")

    def on_message(self, client, userdata, msg):
        if msg.topic == "/version":
            response = self.send_command("*IDN?\n")
            print(f"Instrument response: {response}")

    def send_command(self, command):
        with LOCK:
            # Simulate sending command to UART
            response = "Instrument response: " + command
            return response

    def handle_get_data(self, request):
        with LOCK:
            if request.method == "GET" and request.args.get("item_id"):
                for item in DATA_LIST:
                    if item[0] == request.args.get("item_id"):
                        return self.serialize_item(item), 200
            return self.serialize_error("Item not found"), 404

    def handle_get_data_item(self, request):
        with LOCK:
            item_id = request.args.get("item_id")
            for item in DATA_LIST:
                if item[0] == item_id:
                    return self.serialize_item(item), 200
            return self.serialize_error("Item not found"), 404

    def handle_post_data(self, request):
        with LOCK:
            data = request.json
            if not data.get("name") or not data.get("done"):
                return self.serialize_error("Invalid data"), 400
            new_item = {"id": len(DATA_LIST) + 1, "name": data["name"], "done": data["done"]}
            DATA_LIST.append(new_item)
            return self.serialize_item(new_item), 201

    def serialize_item(self, item):
        return json.dumps(item)

    def serialize_error(self, message):
        return json.dumps({"error": message})

def main():
    uart_manager = UARTManager()
    web_service = WebService()

    try:
        while True:
            # Handle button press for graceful shutdown
            if Button(UP).is_pressed:
                uart_manager.close_connection()
                web_service.app.loop_stop()
                break

            # Handle web requests
            request = request_handler.handle_request()
            response = web_service.handle_request(request)
            request_handler.send_response(response)

    except KeyboardInterrupt:
        uart_manager.close_connection()
        web_service.app.loop_stop()

if __name__ == "__main__":
    main()

