        with LOCK:
            data = request.json
            if not data.get("name") or not data.get("done"):
                return self.serialize_error("Invalid data"), 400
            new_item = {"id": len(DATA_LIST) + 1, "name": data["name"], "done": data["done"]}
            DATA_LIST.append(new_item)
            return self.serialize_item(new_item), 201

    def serialize_item(self, item):
        return json.dumps(item)

    def serialize_error(self, message):
        return json.dumps({"error": message})

def main():
    uart_manager = UARTManager()
    web_service = WebService()

    try:
        while True:
            # Handle button press for graceful shutdown
            if Button(UP).is_pressed:
                uart_manager.close_connection()
                web_service.app.loop_stop()
                break

            # Handle web requests
            request = request_handler.handle_request()
            response = web_service.handle_request(request)
            request_handler.send_response(response)

    except KeyboardInterrupt:
        uart_manager.close_connection()
        web_service.app.loop_stop()

if __name__ == "__main__":
    main()
