def read_pulse_oximeter():
    try:
        # Initialize serial communication
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
        if not ser.is_open:
            raise Exception("Failed to open serial port")

        while True:
            ser.flush()
            data = ser.readline().decode('utf-8').strip()
            if not data:
                continue

            # Split the line by comma
            fields = data.split(',')
            if len(fields) != 2:
                raise ValueError(f"Invalid data format: {data}")

            try:
                heart_rate, spo2 = int(fields[0]), float(fields[1])
            except ValueError:
                raise ValueError(f"Invalid data format: {data}")

            print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")

            # MQTT publish (optional)
            mqtt_client = mqtt.Client()
            mqtt_client.connect("mqtt.server.com", 1883)  # Replace with your MQTT broker
            mqtt_client.publish("pulse_oximeter_data", str(heart_rate) + "," + str(spo2))
            mqtt_client.disconnect()

            time.sleep(1)

    except Exception as e:
        print(f"Error: {e}")
    finally:
        ser.close()

if __name__ == "__main__":
    try:
        read_pulse_oximeter()
    except KeyboardInterrupt:
        print("\nExiting gracefully...")

