            else:
                conn.sendall(b"HTTP/1.1 503 Service Unavailable\r\nContent-Type: text/html\r\n\r\nService temporarily unavailable")
                conn.close()
        except Exception as e:
            print(f"Error handling request: {e}")
        finally:
            ser.close()

if __name__ == "__main__":
    threading.Thread(target=run_server).start()
    mqtt_client.loop_forever()

